example.after:

{
  id: "diabetes-tipo-2",
  nome: "Diabetes Mellitus Tipo 2",
  codigos: {
    icd10: "E11.9",
    ciap2: "T90",
    snomed: "44054006"
  },
  fenotipos: [
    { hpo: "HP:0003074", nome: "Hiperglicemia" },
    { hpo: "HP:0000831", nome: "Resistência insulínica" },
    { hpo: "HP:0000842", nome: "Hiperinsulinemia" }
  ],
  examesRelacionados: [
    { loinc: "1558-6", nome: "Glicemia de jejum" },
    { loinc: "4548-4", nome: "Hemoglobina glicada (HbA1c)" },
    { loinc: "14749-6", nome: "Glicose 2h pós-TOTG" }
  ]
}

example.api_call:

// Buscar LOINC para "HbA1c"
GET https://fhir.loinc.org/CodeSystem/$lookup?system=http://loinc.org&code=4548-4

// Response
{
  "parameter": [
    { "name": "display", "valueString": "Hemoglobin A1c/Hemoglobin.total in Blood" },
    { "name": "property", "part": [
      { "name": "code", "valueCode": "COMPONENT" },
      { "name": "value", "valueString": "Hemoglobin A1c/Hemoglobin.total" }
    ]}
  ]
}

example.integration:

// lib/utils/ontologies/loinc.ts
export const loincCodes = {
  "4548-4": {
    code: "4548-4",
    component: "Hemoglobin A1c/Hemoglobin.total",
    property: "MFr",
    timeAspect: "Pt",
    system: "Bld",
    scaleType: "Qn",
    shortName: "HbA1c MFr Bld",
    longName: "Hemoglobin A1c/Hemoglobin.total in Blood",
    unit: "%",
    referenceRanges: {
      normal: { max: 5.6 },
      prediabetes: { min: 5.7, max: 6.4 },
      diabetes: { min: 6.5 }
    }
  }
};

example.search:

// Buscar PharmGKB para Clopidogrel + CYP2C19
{
  "drug": "Clopidogrel",
  "gene": "CYP2C19",
  "clinicalAnnotation": {
    "evidenceLevel": "1A",
    "phenotypeCategory": "Dosage",
    "summary": "CYP2C19 poor metabolizers have reduced formation of active metabolite...",
    "recommendation": "Consider alternative antiplatelet therapy"
  }
}

example.integration:

// lib/data/medicamentos/cardiovascular.ts
{
  id: "clopidogrel",
  nome: "Clopidogrel",
  codigos: {
    atc: "B01AC04",
    pharmgkb: "PA449053"
  },
  farmacogenetica: {
    gene: {
      nome: "CYP2C19",
      pharmgkbId: "PA124"
    },
    evidenceLevel: "1A",
    fenotipos: [
      {
        tipo: "Poor Metabolizer (*2/*2, *2/*3, *3/*3)",
        impacto: "Redução significativa de eficácia",
        recomendacao: "Considerar prasugrel ou ticagrelor",
        citacao: "cpic-2013-clopidogrel"
      },
      {
        tipo: "Intermediate Metabolizer (*1/*2, *1/*3)",
        impacto: "Redução moderada de eficácia",
        recomendacao: "Considerar dose maior ou agente alternativo",
        citacao: "cpic-2013-clopidogrel"
      }
    ],
    testeRecomendado: "Genotipar CYP2C19 antes de prescrever em SCA/ICP"
  }
}

